def action(identifier, parameters):
    return {"WFWorkflowActionIdentifier": identifier, "WFWorkflowActionParameters": parameters}


def comment(uuid, text):
    return action("is.workflow.actions.comment", {"UUID": uuid, "WFCommentActionText": text})


def output_token(uuid, output_name="Text"):
    return {
        "Value": {"OutputName": output_name, "OutputUUID": uuid, "Type": "ActionOutput"},
        "WFSerializationType": "WFTextTokenAttachment",
    }


def token_string(uuid, text="\ufffc", output_name="Text"):
    return {
        "Value": {
            "attachmentsByRange": {
                "{0, 1}": {"OutputName": output_name, "OutputUUID": uuid, "Type": "ActionOutput"}
            },
            "string": text,
        },
        "WFSerializationType": "WFTextTokenString",
    }


def variable_token(name):
    return {
        "Value": {
            "attachmentsByRange": {
                "{0, 1}": {"Type": "Variable", "VariableName": name}
            },
            "string": "\ufffc",
        },
        "WFSerializationType": "WFTextTokenString",
    }


def build(profile):
    u = profile["uuids"]
    outer_group, inner_group = u[4], u[9]
    prompt = "\ufffc\n\n" + profile["instructions"]
    actions = [
        comment(u[0], f"{profile['name']}\n\n{profile['purpose']}\n\nThis workflow is fully configured by SwiftBot. No prompts or settings need to be edited."),
        comment(u[1], NOTICE),
        action("com.example.swiftbot.SwiftBotWorkflowAttributionIntent", {
            "UUID": u[21],
            "AppIntentDescriptor": {
                "BundleIdentifier": "com.example.swiftbot",
                "Name": "SwiftBot Workflow",
                "AppIntentIdentifier": "SwiftBotWorkflowAttributionIntent",
            },
        }),
        action("is.workflow.actions.gettext", {"UUID": u[2], "WFTextActionText": token_string("EXTENSION", output_name="Text")}),
        comment(u[3], "- Input uses the update notes received from SwiftBot\n- If Input is empty, return a clear bridge error"),
        action("is.workflow.actions.conditional", {
            "UUID": u[5], "GroupingIdentifier": outer_group, "WFControlFlowMode": 0, "WFCondition": 100,
            "WFInput": {"Type": "Variable", "Variable": output_token(u[2])},
        }),
        comment(u[6], "Generate the finished summary with this Shortcut’s built-in editorial style. Web search and follow-up are disabled."),
        action("is.workflow.actions.askllm", {
            "UUID": u[7], "WFLLMModel": "Apple Intelligence", "WFGenerativeResultType": "Text",
            "WFAllowWebSearch": False, "FollowUp": False,
            "WFLLMPrompt": token_string(u[2], prompt),
        }),
        action("is.workflow.actions.gettext", {"UUID": u[8], "WFTextActionText": token_string(u[7], output_name="Response")}),
        comment(u[18], "- Input uses the plain Text response from Use Model above\n- If the response is empty, return a bridge error so SwiftBot can use its fallback"),
        action("is.workflow.actions.conditional", {
            "UUID": u[10], "GroupingIdentifier": inner_group, "WFControlFlowMode": 0, "WFCondition": 100,
            "WFInput": {"Type": "Variable", "Variable": output_token(u[8])},
        }),
        action("is.workflow.actions.setvariable", {"UUID": u[11], "WFInput": output_token(u[8]), "WFVariableName": "Bridge Result"}),
        action("is.workflow.actions.conditional", {"GroupingIdentifier": inner_group, "WFControlFlowMode": 1}),
        action("is.workflow.actions.gettext", {"UUID": u[12], "WFTextActionText": "SWIFTBOT_BRIDGE_ERROR: Apple Intelligence returned an empty response."}),
        action("is.workflow.actions.setvariable", {"UUID": u[13], "WFInput": output_token(u[12]), "WFVariableName": "Bridge Result"}),
        action("is.workflow.actions.conditional", {"UUID": u[14], "GroupingIdentifier": inner_group, "WFControlFlowMode": 2}),
        action("is.workflow.actions.conditional", {"GroupingIdentifier": outer_group, "WFControlFlowMode": 1}),
        action("is.workflow.actions.gettext", {"UUID": u[15], "WFTextActionText": "SWIFTBOT_BRIDGE_ERROR: No update notes were supplied by SwiftBot."}),
        action("is.workflow.actions.setvariable", {"UUID": u[16], "WFInput": output_token(u[15]), "WFVariableName": "Bridge Result"}),
        action("is.workflow.actions.conditional", {"UUID": u[17], "GroupingIdentifier": outer_group, "WFControlFlowMode": 2}),
        comment(u[19], "Return the finished summary or bridge error to SwiftBot as plain text."),
        action("is.workflow.actions.gettext", {"UUID": u[20], "WFTextActionText": variable_token("Bridge Result")}),
    ]

    # Shortcut Input is an ExtensionInput token, not an action output.
    actions[2]["WFWorkflowActionParameters"]["WFTextActionText"] = {
        "Value": {"attachmentsByRange": {"{0, 1}": {"Type": "ExtensionInput"}}, "string": "\ufffc"},
        "WFSerializationType": "WFTextTokenString",
    }

    return {
        "WFWorkflowActions": actions,
        "WFWorkflowClientVersion": "2700.0.4",
        "WFWorkflowClientRelease": "26A0000a",
        "WFWorkflowMinimumClientVersion": 900,
        "WFWorkflowMinimumClientVersionString": "900",
        "WFWorkflowIcon": {
            "WFWorkflowIconGlyphNumber": profile["glyph"],
            "WFWorkflowIconStartColor": profile["color"],
        },
        "WFWorkflowName": profile["name"],
        "WFWorkflowHasOutputFallback": False,
        "WFWorkflowHasShortcutInputVariables": True,
        "WFWorkflowImportQuestions": [],
        "WFWorkflowInputContentItemClasses": ["WFStringContentItem", "WFGenericFileContentItem"],
        "WFWorkflowOutputContentItemClasses": ["WFStringContentItem"],
        "WFWorkflowTypes": [],
    }


def main():
    for profile in PROFILES:
        destination = ROOT / f"{profile['name']}.xml"
        with destination.open("wb") as handle:
            plistlib.dump(build(profile), handle, fmt=plistlib.FMT_XML, sort_keys=False)
        print(destination)


if __name__ == "__main__":
    main()
